args.query:
INSERT INTO measurements (column1, column2, ..., columnN)
SELECT column1, column2, ..., columnN
FROM pilot_session_rows;

UPDATE results_summary SET value = (SELECT AVG(cognitive_score) FROM measurements WHERE condition = 'rested'), n = (SELECT COUNT(*) FROM measurements WHERE condition = 'rested') WHERE metric = 'mean_cognitive_score' AND condition = 'rested';

UPDATE results_summary SET value = (SELECT AVG(reaction_ms) FROM measurements WHERE condition = 'rested'), n = (SELECT COUNT(*) FROM measurements WHERE condition = 'rested') WHERE metric = 'mean_reaction_ms' AND condition = 'rested';

UPDATE results_summary SET value = (SELECT AVG(cognitive_score) FROM measurements WHERE condition = 'sleep_deprived'), n = (SELECT COUNT(*) FROM measurements WHERE condition = 'sleep_deprived') WHERE metric = 'mean_cognitive_score' AND condition = 'sleep_deprived';

UPDATE results_summary SET value = (SELECT AVG(reaction_ms) FROM measurements WHERE condition = 'sleep_deprived'), n = (SELECT COUNT(*) FROM measurements WHERE condition = 'sleep_deprived') WHERE metric = 'mean_reaction_ms' AND condition = 'sleep_deprived';
